import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public final class Solution {
    public enum TransferMethod { GET, POST }

    public static final class TransferDirective {
        private final TransferMethod method;

        public TransferDirective(TransferMethod method) {
            this.method = method;
        }

        public TransferMethod getMethod() {
            return method;
        }
    }

    public static final class OperationOutcome {
        private final TransferDirective directive;
        private final Map<String, String> links;

        public OperationOutcome(TransferDirective directive, Map<String, String> links) {
            this.directive = directive;
            this.links = links == null
                    ? null
                    : Collections.unmodifiableMap(new LinkedHashMap<String, String>(links));
        }

        public TransferDirective getDirective() {
            return directive;
        }

        public Map<String, String> getLinks() {
            return links;
        }
    }

    public static final class TransferRequest {
        private final TransferMethod method;
        private final String destination;

        private TransferRequest(TransferMethod method, String destination) {
            this.method = method;
            this.destination = destination;
        }

        public TransferMethod getMethod() {
            return method;
        }

        public String getDestination() {
            return destination;
        }
    }

    public static final class PaymentException extends Exception {
        public PaymentException(String message) {
            super(message);
        }
    }

    private Solution() {}

    public static TransferRequest buildTransfer(OperationOutcome outcome)
            throws PaymentException {
        if (outcome == null || outcome.getDirective() == null
                || outcome.getDirective().getMethod() == null
                || outcome.getLinks() == null) {
            throw new PaymentException("Incomplete outcome");
        }

        String destination = outcome.getLinks().get("payment");
        if (destination == null || destination.isEmpty() || containsWhitespace(destination)) {
            throw new PaymentException("Invalid payment destination");
        }

        return new TransferRequest(outcome.getDirective().getMethod(), destination);
    }

    private static boolean containsWhitespace(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (Character.isWhitespace(value.charAt(i))) {
                return true;
            }
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    public static final class AddressCommand {
        private final String street;
        private final String city;

        public AddressCommand(String street, String city) {
            this.street = street;
            this.city = city;
        }

        public String getStreet() { return street; }
        public String getCity() { return city; }
    }

    public static final class NewProfileCommand {
        private final String name;
        private final int age;
        private final AddressCommand address;
        private final List<String> emails;

        public NewProfileCommand(String name, int age, AddressCommand address,
                List<String> emails) {
            this.name = name;
            this.age = age;
            this.address = address;
            this.emails = emails;
        }

        public String getName() { return name; }
        public int getAge() { return age; }
        public AddressCommand getAddress() { return address; }
        public List<String> getEmails() { return emails; }
    }

    public static final class Address {
        private final String street;
        private final String city;

        private Address(String street, String city) {
            this.street = street;
            this.city = city;
        }

        public String getStreet() { return street; }
        public String getCity() { return city; }
    }

    public static final class Profile {
        private final String name;
        private final int age;
        private final Address address;
        private final List<String> emails;

        private Profile(String name, int age, Address address, List<String> emails) {
            this.name = name;
            this.age = age;
            this.address = address;
            this.emails = Collections.unmodifiableList(new ArrayList<String>(emails));
        }

        public String getName() { return name; }
        public int getAge() { return age; }
        public Address getAddress() { return address; }
        public List<String> getEmails() { return emails; }
    }

    private Solution() {}

    public static Address mapAddress(AddressCommand command) {
        if (command == null) {
            throw new IllegalArgumentException("Address is required");
        }
        return new Address(command.getStreet(), command.getCity());
    }

    public static Profile mapProfile(NewProfileCommand command) {
        if (command == null || command.getAddress() == null || command.getEmails() == null) {
            throw new IllegalArgumentException("Invalid profile command");
        }
        for (String email : command.getEmails()) {
            if (email == null) {
                throw new IllegalArgumentException("Invalid profile command");
            }
        }
        List<String> emails = new ArrayList<String>(command.getEmails());
        return new Profile(command.getName(), command.getAge(),
                mapAddress(command.getAddress()), emails);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public final class Solution {
    private Solution() {}

    public interface Stage {
        String apply(String input);
    }

    public static final class TrimStage implements Stage {
        public String apply(String input) {
            return input.trim();
        }
    }

    public static final class UpperStage implements Stage {
        public String apply(String input) {
            return input.toUpperCase(Locale.ROOT);
        }
    }

    public static final class Workflow {
        private final List<Stage> stages;

        public Workflow(List<Stage> stages) {
            if (stages == null) {
                throw new IllegalArgumentException("Invalid stages");
            }
            for (Stage stage : stages) {
                if (stage == null) {
                    throw new IllegalArgumentException("Invalid stages");
                }
            }
            this.stages = new ArrayList<Stage>(stages);
        }

        public String run(String input) {
            if (input == null) {
                throw new IllegalArgumentException("input must not be null");
            }
            String value = input;
            for (Stage stage : stages) {
                value = stage.apply(value);
                if (value == null) {
                    throw new IllegalArgumentException("A stage returned null");
                }
            }
            return value;
        }
    }

    public static String execute(String input, List<Stage> stages) {
        return new Workflow(stages).run(input);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

public final class Solution {
    public static final class Bundle {
        private final Map<String, Map<String, String>> resources;
        private final List<String> recipes;
        private final Map<String, String> language;

        private Bundle(Map<String, Map<String, String>> resources,
                List<String> recipes, Map<String, String> language) {
            this.resources = resources;
            this.recipes = recipes;
            this.language = language;
        }

        public Map<String, Map<String, String>> getResources() { return resources; }
        public List<String> getRecipes() { return recipes; }
        public Map<String, String> getLanguage() { return language; }
    }

    private Solution() {}

    private static void requireMap(Map<?, ?> map) {
        if (map == null) {
            throw new IllegalArgumentException("null map");
        }
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null) {
                throw new IllegalArgumentException("null map entry");
            }
        }
    }

    public static Bundle prepare(Set<String> enabledModules,
            Map<String, Map<String, String>> resources,
            Map<String, List<String>> recipeDefinitions,
            Map<String, String> clientLanguage, boolean client) {
        if (enabledModules == null) {
            throw new IllegalArgumentException("invalid modules");
        }
        for (String module : enabledModules) {
            if (module == null) {
                throw new IllegalArgumentException("invalid modules");
            }
        }

        requireMap(resources);
        requireMap(recipeDefinitions);
        requireMap(clientLanguage);

        for (Map<String, String> moduleResources : resources.values()) {
            requireMap(moduleResources);
        }
        for (List<String> definitions : recipeDefinitions.values()) {
            if (definitions == null) {
                throw new IllegalArgumentException("invalid recipe list");
            }
            for (String definition : definitions) {
                if (definition == null) {
                    throw new IllegalArgumentException("invalid recipe list");
                }
            }
        }

        Map<String, Map<String, String>> keptResources = new LinkedHashMap<String, Map<String, String>>();
        for (Map.Entry<String, Map<String, String>> entry : resources.entrySet()) {
            if (enabledModules.contains(entry.getKey())) {
                Map<String, String> nestedCopy = new LinkedHashMap<String, String>(entry.getValue());
                keptResources.put(entry.getKey(), Collections.unmodifiableMap(nestedCopy));
            }
        }

        List<String> keptRecipes = new ArrayList<String>();
        for (String module : new TreeSet<String>(enabledModules)) {
            List<String> definitions = recipeDefinitions.get(module);
            if (definitions != null) {
                List<String> sorted = new ArrayList<String>(definitions);
                Collections.sort(sorted);
                keptRecipes.addAll(sorted);
            }
        }

        Map<String, String> language = client
                ? new LinkedHashMap<String, String>(clientLanguage)
                : new LinkedHashMap<String, String>();
        return new Bundle(
                Collections.unmodifiableMap(keptResources),
                Collections.unmodifiableList(keptRecipes),
                Collections.unmodifiableMap(language));
    }
}

import java.util.Map;
import java.util.TreeMap;

public final class Solution {
    private static final Map<String, String> DATA = new TreeMap<String, String>();

    private Solution() {}

    public static synchronized boolean write(String key, String value) {
        if (!validKey(key) || value == null || value.length() > 256) {
            return false;
        }
        DATA.put(key, value);
        return true;
    }

    public static synchronized String read(String key) {
        return validKey(key) ? DATA.get(key) : null;
    }

    public static synchronized String[] snapshot() {
        String[] result = new String[DATA.size()];
        int index = 0;
        for (Map.Entry<String, String> entry : DATA.entrySet()) {
            result[index++] = entry.getKey() + "=" + entry.getValue();
        }
        return result;
    }

    public static synchronized void clear() {
        DATA.clear();
    }

    private static boolean validKey(String key) {
        if (key == null || key.length() < 1 || key.length() > 32) {
            return false;
        }
        for (int i = 0; i < key.length(); i++) {
            char character = key.charAt(i);
            if (!(character >= 'a' && character <= 'z')
                    && !(character >= 'A' && character <= 'Z')
                    && !(character >= '0' && character <= '9')) {
                return false;
            }
        }
        return true;
    }
}

from collections.abc import Mapping
from copy import deepcopy


def clean_catalog(entries, blocked_directories, blocked_suffixes, scoped_suffixes, dry_run):
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")
    if not isinstance(blocked_directories, (tuple, list, set, frozenset)):
        raise TypeError("blocked_directories must be a collection")
    if not isinstance(blocked_suffixes, (tuple, list, set, frozenset)):
        raise TypeError("blocked_suffixes must be a collection")
    if not isinstance(scoped_suffixes, Mapping):
        raise TypeError("scoped_suffixes must be a mapping")
    if type(dry_run) is not bool:
        raise TypeError("dry_run must be a boolean")

    def validate_strings(values, name):
        for value in values:
            if not isinstance(value, str):
                raise TypeError(f"{name} must contain strings")
            if not value:
                raise ValueError(f"{name} must not contain empty strings")

    validate_strings(blocked_directories, "blocked_directories")
    validate_strings(blocked_suffixes, "blocked_suffixes")
    blocked_dirs = frozenset(blocked_directories)
    endings = tuple(blocked_suffixes)

    scopes = []
    for prefix, suffix_values in scoped_suffixes.items():
        if not isinstance(prefix, tuple):
            raise TypeError("scope prefixes must be tuples")
        if not prefix:
            raise ValueError("scope prefixes must not be empty")
        validate_strings(prefix, "scope prefix")
        if not isinstance(suffix_values, tuple):
            raise TypeError("scoped suffix collections must be tuples")
        validate_strings(suffix_values, "scoped suffixes")
        scopes.append((prefix, suffix_values))

    candidates = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise TypeError("each entry must be a dictionary")
        if set(entry) != {"path", "kind", "metadata"}:
            raise ValueError("each entry must have exactly path, kind, and metadata")
        path = entry["path"]
        kind = entry["kind"]
        if not isinstance(path, tuple):
            raise TypeError("path must be a tuple")
        if not path:
            raise ValueError("path must not be empty")
        validate_strings(path, "path")
        if not isinstance(kind, str):
            raise TypeError("kind must be a string")
        if kind not in {"file", "directory"}:
            raise ValueError("kind must be file or directory")

        candidate = any(component in blocked_dirs for component in path)
        if kind == "file" and not candidate:
            candidate = any(path[-1].endswith(suffix) for suffix in endings)
        if kind == "file" and not candidate:
            for prefix, suffix_values in scopes:
                if path[:len(prefix)] == prefix and any(
                    path[-1].endswith(suffix) for suffix in suffix_values
                ):
                    candidate = True
                    break
        candidates.append(candidate)

    removed = [deepcopy(entry) for entry, candidate in zip(entries, candidates) if candidate]
    if dry_run:
        remaining = [deepcopy(entry) for entry in entries]
    else:
        remaining = [deepcopy(entry) for entry, candidate in zip(entries, candidates) if not candidate]
    return {"removed": removed, "remaining": remaining}

from collections.abc import Mapping
from copy import deepcopy


class SignalSpec:
    def __init__(self, code, unit, labels=None):
        if not isinstance(code, str):
            raise TypeError("code must be a string")
        if not code:
            raise ValueError("code must not be empty")
        if not isinstance(unit, str):
            raise TypeError("unit must be a string")
        if labels is None:
            labels = {}
        if not isinstance(labels, Mapping):
            raise TypeError("labels must be a mapping")
        self.code = code
        self.unit = unit
        self.labels = deepcopy(dict(labels))


class SignalCatalog:
    def __init__(self, specs=None):
        self._specs = []
        if specs is not None:
            for spec in specs:
                self.add(spec)

    def add(self, spec):
        if not isinstance(spec, SignalSpec):
            raise TypeError("spec must be a SignalSpec")
        if any(existing.code == spec.code for existing in self._specs):
            raise ValueError("duplicate code")
        self._specs.append(deepcopy(spec))

    def all(self):
        return deepcopy(self._specs)

    def find(self, code):
        if not isinstance(code, str):
            raise TypeError("code must be a string")
        for spec in self._specs:
            if spec.code == code:
                return deepcopy(spec)
        return None

import copy
import re
from collections.abc import Mapping


_SLUG = re.compile(r"[a-z0-9-]+\Z")


class RecipeShelf:
    def __init__(self, recipes=()):
        self._recipes = {}
        for recipe in recipes:
            self.add(recipe)

    @staticmethod
    def _normalize(recipe):
        if not isinstance(recipe, Mapping) or set(recipe) != {"slug", "title", "tags"}:
            raise ValueError("recipe must contain exactly slug, title, and tags")
        slug = recipe["slug"]
        if not isinstance(slug, str) or not _SLUG.fullmatch(slug):
            raise ValueError("invalid slug")
        title = recipe["title"]
        if not isinstance(title, str) or not title.strip():
            raise ValueError("invalid title")
        try:
            tags = list(recipe["tags"])
        except TypeError:
            raise TypeError("tags must be iterable") from None
        if any(not isinstance(tag, str) or not tag.strip() for tag in tags):
            raise ValueError("invalid tag")
        return {"slug": slug, "title": title.strip(), "tags": [tag.strip() for tag in tags]}

    def add(self, recipe):
        normalized = self._normalize(recipe)
        if normalized["slug"] in self._recipes:
            raise ValueError("duplicate slug")
        self._recipes[normalized["slug"]] = normalized

    def edit(self, slug, *, title=None, tags=None):
        if slug not in self._recipes:
            raise KeyError(slug)
        candidate = copy.deepcopy(self._recipes[slug])
        if title is not None:
            candidate["title"] = title
        if tags is not None:
            try:
                candidate["tags"] = list(tags)
            except TypeError:
                raise TypeError("tags must be iterable") from None
        normalized = self._normalize(candidate)
        self._recipes[slug] = normalized
        return copy.deepcopy(normalized)

    def detail(self, slug):
        if slug not in self._recipes:
            raise KeyError(slug)
        return copy.deepcopy(self._recipes[slug])

    def list_all(self):
        return [copy.deepcopy(self._recipes[slug]) for slug in sorted(self._recipes)]

    def resolve(self, path):
        if path == "/":
            return "page", {"message": "Recipe shelf"}
        if path == "/start":
            return "redirect", "/recipes"
        if path == "/recipes":
            return "page", self.list_all()
        prefix = "/recipes/"
        if isinstance(path, str) and path.startswith(prefix) and path[len(prefix):] and "/" not in path[len(prefix):]:
            return "page", self.detail(path[len(prefix):])
        raise KeyError(path)

_RULES = {
    "quartz": ({"quartz.mod"}, (".qproj",)),
    "ember": ({"ember.lock"}, ()),
    "orbit": ({"orbit.map"}, (".orb",)),
}


def _path_parts(path, allow_root):
    if not isinstance(path, str):
        raise TypeError("paths must be strings")
    if not path.startswith("/"):
        raise ValueError("path must be absolute")
    if path == "/":
        if allow_root:
            return []
        raise ValueError("document path must contain a filename")
    parts = path[1:].split("/")
    if any(part in {"", ".", ".."} for part in parts):
        raise ValueError("path must be normalized")
    return parts


def nearest_bundle(document_path, profile, entries):
    document_parts = _path_parts(document_path, False)
    if not isinstance(profile, str):
        raise TypeError("profile must be a string")
    if profile not in _RULES:
        raise ValueError("unknown profile")
    if not isinstance(entries, set):
        raise TypeError("entries must be a set")

    normalized_entries = set()
    for entry in entries:
        _path_parts(entry, True)
        normalized_entries.add(entry)

    directory_parts = document_parts[:-1]
    directories = [
        "/" + "/".join(directory_parts[:length]) if length else "/"
        for length in range(len(directory_parts), -1, -1)
    ]

    exact, suffixes = _RULES[profile]
    for directory in directories:
        prefix = directory.rstrip("/") + "/"
        for entry in normalized_entries:
            if not entry.startswith(prefix):
                continue
            remainder = entry[len(prefix):]
            if "/" not in remainder and (remainder in exact or remainder.endswith(suffixes)):
                return directory

    for directory in directories:
        marker = directory.rstrip("/") + "/.anchor"
        if marker in normalized_entries:
            return directory

    return directories[0]

from collections.abc import Mapping, Sequence
from copy import deepcopy


def catalog_snapshot(items, collections, page, page_size):
    """Validate and return a detached, consistently ordered catalog page."""
    if (isinstance(page, bool) or not isinstance(page, int) or page <= 0 or
            isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0):
        raise ValueError("page and page_size must be positive integers")

    item_list = []
    by_id = {}
    for item in items:
        if not isinstance(item, Mapping) or set(item) != {"id", "title", "votes"}:
            raise TypeError("invalid item record")
        snapshot = dict(item)
        if not isinstance(snapshot["id"], str) or not snapshot["id"]:
            raise ValueError("item id must be non-empty")
        if not isinstance(snapshot["title"], str) or not snapshot["title"]:
            raise ValueError("item title must be non-empty")
        if isinstance(snapshot["votes"], bool) or not isinstance(snapshot["votes"], int):
            raise TypeError("votes must be an integer")
        if snapshot["id"] in by_id:
            raise ValueError("duplicate item id")
        detached = deepcopy(snapshot)
        item_list.append(detached)
        by_id[detached["id"]] = detached

    collection_list = []
    collection_ids = set()
    for collection in collections:
        if not isinstance(collection, Mapping) or set(collection) != {"id", "name", "item_ids"}:
            raise TypeError("invalid collection record")
        snapshot = dict(collection)
        if not isinstance(snapshot["id"], str) or not snapshot["id"]:
            raise ValueError("collection id must be non-empty")
        if not isinstance(snapshot["name"], str) or not snapshot["name"]:
            raise ValueError("collection name must be non-empty")
        if snapshot["id"] in collection_ids:
            raise ValueError("duplicate collection id")
        item_ids = snapshot["item_ids"]
        if isinstance(item_ids, (str, bytes)) or not isinstance(item_ids, Sequence):
            raise TypeError("item_ids must be a sequence")
        for item_id in item_ids:
            if not isinstance(item_id, str):
                raise TypeError("item IDs must be strings")
            if item_id not in by_id:
                raise ValueError("unknown item id")
        collection_ids.add(snapshot["id"])
        collection_list.append(deepcopy(snapshot))

    ordered_items = sorted(item_list, key=lambda item: (-item["votes"], item["title"], item["id"]))
    ordered_collections = sorted(collection_list, key=lambda value: (value["name"], value["id"]))
    start = (page - 1) * page_size
    stop = start + page_size

    output_collections = []
    for collection in ordered_collections[start:stop]:
        copied = deepcopy(collection)
        copied["resolved_items"] = [deepcopy(by_id[item_id]) for item_id in collection["item_ids"]]
        output_collections.append(copied)

    return {
        "item_total": len(item_list),
        "collection_total": len(collection_list),
        "items": [deepcopy(item) for item in ordered_items[start:stop]],
        "collections": output_collections,
    }

use std::collections::{BTreeMap, BTreeSet};

pub enum RegistryError {
    InvalidName(String),
    UnknownScope(String),
    Duplicate(String),
}

#[derive(Clone)]
pub struct TagRegistry {
    scopes: BTreeMap<String, BTreeSet<String>>,
}

fn valid_name(name: &str) -> bool {
    let mut bytes = name.bytes();
    match bytes.next() {
        Some(first) if first.is_ascii_alphabetic() || first == b'_' => {}
        _ => return false,
    }
    bytes.all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
}

impl TagRegistry {
    pub fn new() -> Self {
        Self {
            scopes: BTreeMap::new(),
        }
    }

    pub fn register_scope(&mut self, scope: &str) -> Result<(), RegistryError> {
        if !valid_name(scope) {
            return Err(RegistryError::InvalidName(scope.to_owned()));
        }
        if self.scopes.contains_key(scope) {
            return Err(RegistryError::Duplicate(scope.to_owned()));
        }
        self.scopes.insert(scope.to_owned(), BTreeSet::new());
        Ok(())
    }

    pub fn register_tag(&mut self, scope: &str, tag: &str) -> Result<(), RegistryError> {
        if !valid_name(scope) {
            return Err(RegistryError::InvalidName(scope.to_owned()));
        }
        if !valid_name(tag) {
            return Err(RegistryError::InvalidName(tag.to_owned()));
        }
        let tags = self
            .scopes
            .get_mut(scope)
            .ok_or_else(|| RegistryError::UnknownScope(scope.to_owned()))?;
        if !tags.insert(tag.to_owned()) {
            return Err(RegistryError::Duplicate(format!("{}::{}", scope, tag)));
        }
        Ok(())
    }

    pub fn register_batch(
        &mut self,
        enabled: bool,
        entries: &[(&str, &str)],
    ) -> Result<(), RegistryError> {
        if !enabled {
            return Ok(());
        }
        let mut candidate = self.clone();
        for &(scope, tag) in entries {
            candidate.register_tag(scope, tag)?;
        }
        *self = candidate;
        Ok(())
    }

    pub fn tags(&self) -> Vec<String> {
        let mut result: Vec<String> = self
            .scopes
            .iter()
            .flat_map(|(scope, tags)| {
                tags.iter().map(move |tag| format!("{}::{}", scope, tag))
            })
            .collect();
        result.sort();
        result
    }
}

use std::collections::BTreeMap;

pub type AccountId = String;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Transfer {
    pub from: AccountId,
    pub to: AccountId,
    pub amount: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerError {
    EmptyAccount,
    DuplicateAccount,
    UnknownAccount,
    SameAccount,
    ZeroAmount,
    InsufficientFunds,
    Overflow,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ledger {
    balances: BTreeMap<AccountId, u64>,
    supply: u64,
}

impl Ledger {
    pub fn new(origin: AccountId, supply: u64) -> Result<Self, LedgerError> {
        if origin.is_empty() {
            return Err(LedgerError::EmptyAccount);
        }
        let mut balances = BTreeMap::new();
        balances.insert(origin, supply);
        Ok(Self { balances, supply })
    }

    pub fn add_account(&mut self, id: AccountId) -> Result<(), LedgerError> {
        if id.is_empty() {
            return Err(LedgerError::EmptyAccount);
        }
        if self.balances.contains_key(&id) {
            return Err(LedgerError::DuplicateAccount);
        }
        self.balances.insert(id, 0);
        Ok(())
    }

    pub fn balance(&self, id: &str) -> Option<u64> {
        self.balances.get(id).copied()
    }

    pub fn total(&self) -> u64 {
        self.supply
    }

    pub fn apply(&mut self, transfer: &Transfer) -> Result<(), LedgerError> {
        if transfer.amount == 0 {
            return Err(LedgerError::ZeroAmount);
        }
        if transfer.from == transfer.to {
            return Err(LedgerError::SameAccount);
        }

        let from = self
            .balance(&transfer.from)
            .ok_or(LedgerError::UnknownAccount)?;
        let to = self
            .balance(&transfer.to)
            .ok_or(LedgerError::UnknownAccount)?;
        if from < transfer.amount {
            return Err(LedgerError::InsufficientFunds);
        }

        let new_from = from
            .checked_sub(transfer.amount)
            .ok_or(LedgerError::InsufficientFunds)?;
        let new_to = to
            .checked_add(transfer.amount)
            .ok_or(LedgerError::Overflow)?;

        self.balances.insert(transfer.from.clone(), new_from);
        self.balances.insert(transfer.to.clone(), new_to);
        Ok(())
    }

    pub fn apply_batch(&mut self, transfers: &[Transfer]) -> Result<(), LedgerError> {
        let snapshot = self.balances.clone();
        for transfer in transfers {
            if let Err(error) = self.apply(transfer) {
                self.balances = snapshot;
                return Err(error);
            }
        }
        Ok(())
    }
}

Implement a standard-library-only Rust library for totaling an in-memory grid column across named tables.

Expose this exact API from `solution.rs`:

```rust
#[derive(Clone, Debug, PartialEq)]
pub enum Cell {
    Number(f64),
    Text(String),
    Empty,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Table {
    pub name: String,
    pub rows: Vec<Vec<Cell>>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ColumnTotal {
    pub table_name: String,
    pub present: bool,
    pub sum: f64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ColumnError {
    InvalidLabel,
    LabelOverflow,
}

pub fn total_column(tables: &[Table], label: &str) -> Result<Vec<ColumnTotal>, ColumnError>;
```

A column label is a nonempty sequence of uppercase ASCII letters using spreadsheet-style numbering: `A` is index 0, `Z` is 25, `AA` is 26. Empty labels, lowercase letters, digits, whitespace, and punctuation produce `InvalidLabel`. If conversion cannot fit in `usize`, return `LabelOverflow`.

For each table, preserve input ordering and return one result. `present` is true if at least one row has a cell at the selected index, regardless of that cell's variant. Sum only `Number` cells; ignore text and empty cells. Missing cells in short rows are ignored. If the column is absent, set `present` to false and `sum` to `0.0`. Empty input returns an empty vector. Do not mutate the tables.

Return only the complete source file; do not include Markdown fences or prose.

#[derive(Clone, Debug, PartialEq)]
pub enum Cell {
    Number(f64),
    Text(String),
    Empty,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Table {
    pub name: String,
    pub rows: Vec<Vec<Cell>>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ColumnTotal {
    pub table_name: String,
    pub present: bool,
    pub sum: f64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ColumnError {
    InvalidLabel,
    LabelOverflow,
}

fn column_index(label: &str) -> Result<usize, ColumnError> {
    if label.is_empty() || !label.bytes().all(|b| b.is_ascii_uppercase()) {
        return Err(ColumnError::InvalidLabel);
    }

    let mut bytes = label.bytes();
    let first = bytes.next().ok_or(ColumnError::InvalidLabel)?;
    let mut index = usize::from(first - b'A');
    for byte in bytes {
        let digit = usize::from(byte - b'A') + 1;
        index = index
            .checked_mul(26)
            .and_then(|value| value.checked_add(25))
            .and_then(|value| value.checked_add(digit))
            .ok_or(ColumnError::LabelOverflow)?;
    }
    Ok(index)
}

pub fn total_column(tables: &[Table], label: &str) -> Result<Vec<ColumnTotal>, ColumnError> {
    let index = column_index(label)?;
    Ok(tables
        .iter()
        .map(|table| {
            let mut present = false;
            let mut sum = 0.0;
            for row in &table.rows {
                if let Some(cell) = row.get(index) {
                    present = true;
                    if let Cell::Number(value) = cell {
                        sum += value;
                    }
                }
            }
            ColumnTotal {
                table_name: table.name.clone(),
                present,
                sum,
            }
        })
        .collect())
}

pub fn heaviest_route(
    node_count: usize,
    root: usize,
    edges: &[(usize, usize, i64)],
) -> Option<i64> {
    if node_count == 0 || root >= node_count || edges.len() != node_count - 1 {
        return None;
    }

    let mut children = vec![Vec::<(usize, i64)>::new(); node_count];
    let mut parents = vec![0usize; node_count];
    for &(parent, child, weight) in edges {
        if parent >= node_count || child >= node_count || parent == child {
            return None;
        }
        parents[child] = parents[child].checked_add(1)?;
        if parents[child] > 1 {
            return None;
        }
        children[parent].push((child, weight));
    }

    if parents[root] != 0
        || parents
            .iter()
            .enumerate()
            .any(|(node, &count)| node != root && count != 1)
    {
        return None;
    }

    let mut seen = vec![false; node_count];
    let mut stack = vec![(root, 0i64)];
    let mut best: Option<i64> = None;

    while let Some((node, total)) = stack.pop() {
        if seen[node] {
            return None;
        }
        seen[node] = true;

        if children[node].is_empty() {
            best = Some(best.map_or(total, |current| current.max(total)));
            continue;
        }

        for &(child, weight) in &children[node] {
            let next_total = total.checked_add(weight)?;
            stack.push((child, next_total));
        }
    }

    if seen.iter().all(|&value| value) {
        best
    } else {
        None
    }
}

use std::collections::{BTreeSet, HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Passage {
    pub from: String,
    pub to: String,
    pub minutes: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Tour {
    pub rooms: Vec<String>,
    pub minutes: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TourError {
    EmptyRoom,
    SelfPassage,
    DuplicatePassage,
    CostOverflow,
}

pub fn analyze_tours(passages: &[Passage]) -> Result<Vec<Tour>, TourError> {
    let mut names = BTreeSet::new();
    let mut pairs = HashSet::new();
    let mut costs = HashMap::new();

    for passage in passages {
        if passage.from.is_empty() || passage.to.is_empty() {
            return Err(TourError::EmptyRoom);
        }
        if passage.from == passage.to {
            return Err(TourError::SelfPassage);
        }
        let pair = if passage.from < passage.to {
            (passage.from.clone(), passage.to.clone())
        } else {
            (passage.to.clone(), passage.from.clone())
        };
        if !pairs.insert(pair.clone()) {
            return Err(TourError::DuplicatePassage);
        }
        names.insert(passage.from.clone());
        names.insert(passage.to.clone());
        costs.insert(pair, passage.minutes);
    }

    let names: Vec<String> = names.into_iter().collect();
    if names.is_empty() {
        return Ok(Vec::new());
    }

    fn build(
        names: &[String],
        costs: &HashMap<(String, String), u64>,
        used: &mut [bool],
        path: &mut Vec<String>,
        total: Option<u64>,
        out: &mut Vec<Tour>,
        overflowed_tour: &mut bool,
    ) {
        if path.len() == names.len() {
            match total {
                Some(minutes) => out.push(Tour {
                    rooms: path.clone(),
                    minutes,
                }),
                None => *overflowed_tour = true,
            }
            return;
        }

        for index in 0..names.len() {
            if used[index] {
                continue;
            }
            let next_total = if let Some(previous) = path.last() {
                let pair = if previous < &names[index] {
                    (previous.clone(), names[index].clone())
                } else {
                    (names[index].clone(), previous.clone())
                };
                let Some(edge) = costs.get(&pair) else {
                    continue;
                };
                total.and_then(|value| value.checked_add(*edge))
            } else {
                total
            };

            used[index] = true;
            path.push(names[index].clone());
            build(
                names,
                costs,
                used,
                path,
                next_total,
                out,
                overflowed_tour,
            );
            path.pop();
            used[index] = false;
        }
    }

    let mut answer = Vec::new();
    let mut overflowed_tour = false;
    build(
        &names,
        &costs,
        &mut vec![false; names.len()],
        &mut Vec::new(),
        Some(0),
        &mut answer,
        &mut overflowed_tour,
    );

    if overflowed_tour {
        return Err(TourError::CostOverflow);
    }
    answer.sort_by(|a, b| a.rooms.cmp(&b.rooms));
    Ok(answer)
}

pub struct DeviceSpec {
    pub id: String,
    pub enabled: bool,
    pub tags: Vec<String>,
}

pub enum ParseDeviceError {
    EmptyInput,
    WrongFieldCount,
    InvalidId,
    InvalidEnabled,
    InvalidTag,
}

fn valid_token(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub fn parse_device_spec(input: &str) -> Result<DeviceSpec, ParseDeviceError> {
    if input.trim().is_empty() {
        return Err(ParseDeviceError::EmptyInput);
    }

    let fields: Vec<&str> = input.split(',').collect();
    if fields.len() != 3 {
        return Err(ParseDeviceError::WrongFieldCount);
    }

    let id = fields[0].trim();
    if !valid_token(id) {
        return Err(ParseDeviceError::InvalidId);
    }

    let enabled = match fields[1].trim() {
        "on" => true,
        "off" => false,
        _ => return Err(ParseDeviceError::InvalidEnabled),
    };

    let tag_field = fields[2].trim();
    let tags = if tag_field.is_empty() {
        Vec::new()
    } else {
        tag_field
            .split(':')
            .map(|raw| {
                let tag = raw.trim();
                if valid_token(tag) {
                    Ok(tag.to_owned())
                } else {
                    Err(ParseDeviceError::InvalidTag)
                }
            })
            .collect::<Result<Vec<_>, _>>()?
    };

    Ok(DeviceSpec {
        id: id.to_owned(),
        enabled,
        tags,
    })
}

