import (
	"errors"
	"strings"
)

type Route struct {
	Method  string
	Pattern string
	Name    string
}

type Router struct {
	routes []Route
}

type routeIdentity struct {
	method  string
	pattern string
}

func splitPath(path string, allowPlaceholders bool) ([]string, error) {
	if path == "/" {
		return []string{}, nil
	}
	if !strings.HasPrefix(path, "/") || strings.HasSuffix(path, "/") || strings.Contains(path, "//") {
		return nil, errors.New("invalid path")
	}
	parts := strings.Split(path[1:], "/")
	for _, part := range parts {
		if part == "" {
			return nil, errors.New("invalid path")
		}
		if !allowPlaceholders && strings.ContainsAny(part, "{}") {
			return nil, errors.New("placeholders not allowed")
		}
	}
	return parts, nil
}

func placeholder(segment string) (string, bool) {
	if len(segment) >= 3 && segment[0] == '{' && segment[len(segment)-1] == '}' {
		name := segment[1 : len(segment)-1]
		if !strings.ContainsAny(name, "{}") {
			return name, true
		}
	}
	return "", false
}

func NewRouter(routes []Route) (*Router, error) {
	seenRoutes := make(map[routeIdentity]bool)
	copiedRoutes := append([]Route(nil), routes...)
	for _, route := range copiedRoutes {
		if route.Method == "" || route.Name == "" {
			return nil, errors.New("method and name are required")
		}
		parts, err := splitPath(route.Pattern, true)
		if err != nil {
			return nil, err
		}
		seenParams := make(map[string]bool)
		for _, part := range parts {
			if strings.ContainsAny(part, "{}") {
				name, ok := placeholder(part)
				if !ok || seenParams[name] {
					return nil, errors.New("invalid placeholder")
				}
				seenParams[name] = true
			}
		}
		identity := routeIdentity{method: route.Method, pattern: route.Pattern}
		if seenRoutes[identity] {
			return nil, errors.New("duplicate route")
		}
		seenRoutes[identity] = true
	}
	return &Router{routes: copiedRoutes}, nil
}

func (r *Router) Resolve(method, path string) (string, map[string]string, bool) {
	parts, err := splitPath(path, false)
	if err != nil || method == "" {
		return "", nil, false
	}
	for _, route := range r.routes {
		if route.Method != method {
			continue
		}
		pattern, _ := splitPath(route.Pattern, true)
		if len(parts) != len(pattern) {
			continue
		}
		params := make(map[string]string)
		matched := true
		for index, segment := range pattern {
			if name, ok := placeholder(segment); ok {
				params[name] = parts[index]
			} else if segment != parts[index] {
				matched = false
				break
			}
		}
		if matched {
			return route.Name, params, true
		}
	}
	return "", nil, false
}

