import (
	"errors"
	"fmt"
	"strings"
)

type Segment struct {
	Code string
	Span int
}

type Layout struct {
	Material      string
	Capacity, Gap int
	Segments      []Segment
	Marks         []int
}

func EncodeLayout(layout Layout) (string, error) {
	if layout.Material == "" || layout.Capacity < 0 || layout.Gap < 0 {
		return "", errors.New("invalid layout")
	}

	used := 0
	for index, segment := range layout.Segments {
		if segment.Code == "" || segment.Span <= 0 {
			return "", errors.New("invalid segment")
		}
		if index > 0 {
			if layout.Gap > layout.Capacity-used {
				return "", errors.New("layout exceeds capacity")
			}
			used += layout.Gap
		}
		if segment.Span > layout.Capacity-used {
			return "", errors.New("layout exceeds capacity")
		}
		used += segment.Span
	}

	for _, mark := range layout.Marks {
		if mark < 0 || mark > layout.Capacity {
			return "", errors.New("invalid mark")
		}
	}

	var builder strings.Builder
	fmt.Fprintf(&builder, "LAYOUT/1\n[base]\nmaterial=%s\ncapacity=%d\n[segments]\n", layout.Material, layout.Capacity)
	for _, segment := range layout.Segments {
		fmt.Fprintf(&builder, "%s:%d\n", segment.Code, segment.Span)
	}
	builder.WriteString("[marks]\n")
	for _, mark := range layout.Marks {
		fmt.Fprintf(&builder, "%d\n", mark)
	}
	fmt.Fprintf(&builder, "[totals]\nused=%d\nremaining=%d\n", used, layout.Capacity-used)
	return builder.String(), nil
}

package solution

import (
	"errors"
	"strings"
)

var ErrInvalidLevel = errors.New("invalid log level")

type Severity int

const (
	Debug Severity = iota
	Info
	Warn
	Error
	Fatal
)

type LogEntry struct {
	Level   Severity
	Message string
}

func asciiLower(value string) string {
	bytes := []byte(value)
	for index, character := range bytes {
		if character >= 'A' && character <= 'Z' {
			bytes[index] = character + ('a' - 'A')
		}
	}
	return string(bytes)
}

func ParseSeverity(value string) (Severity, error) {
	switch asciiLower(strings.TrimSpace(value)) {
	case "debug":
		return Debug, nil
	case "info":
		return Info, nil
	case "warn":
		return Warn, nil
	case "error":
		return Error, nil
	case "fatal":
		return Fatal, nil
	default:
		return Debug, ErrInvalidLevel
	}
}

func FilterLogs(minimum string, entries []LogEntry) ([]LogEntry, error) {
	level, err := ParseSeverity(minimum)
	if err != nil {
		return nil, ErrInvalidLevel
	}
	for _, entry := range entries {
		if entry.Level < Debug || entry.Level > Fatal {
			return nil, ErrInvalidLevel
		}
	}
	result := make([]LogEntry, 0)
	for _, entry := range entries {
		if entry.Level >= level {
			result = append(result, entry)
		}
	}
	return result, nil
}

package solution

import (
	"errors"
	"strings"
)

type InventoryItem struct {
	Code      string
	Name      string
	CostCents int64
	Group     string
	Notes     string
}

type InventoryPatch struct {
	Name      *string
	CostCents *int64
	Group     *string
	Notes     *string
}

func UpdateInventoryItem(table map[string]InventoryItem, code string, patch InventoryPatch) (InventoryItem, error) {
	item, exists := table[code]
	if code == "" {
		if exists {
			return item, errors.New("empty code")
		}
		return InventoryItem{}, errors.New("empty code")
	}
	if !exists {
		return InventoryItem{}, errors.New("item not found")
	}

	updated := item
	if patch.Name != nil {
		if strings.TrimSpace(*patch.Name) == "" {
			return item, errors.New("invalid name")
		}
		updated.Name = *patch.Name
	}
	if patch.CostCents != nil {
		if *patch.CostCents < 0 {
			return item, errors.New("negative cost")
		}
		updated.CostCents = *patch.CostCents
	}
	if patch.Group != nil {
		if strings.TrimSpace(*patch.Group) == "" {
			return item, errors.New("invalid group")
		}
		updated.Group = *patch.Group
	}
	if patch.Notes != nil {
		updated.Notes = *patch.Notes
	}

	table[code] = updated
	return updated, nil
}
